"""Steady fixed-contact-point calibration for measured mode responses.

The short impulse calibration is useful for detecting contact, but it mixes
impact transients with the response one wants to use in a quasi-static CLF
model.  This module keeps a pusher ball at one declared body-frame contact
point, drives it through a real distance, and fits only the continuous-contact
segment after warm-up.
"""

from __future__ import annotations

from dataclasses import dataclass
import json

import numpy as np

from .evaluation import json_safe
from .library import ModeLibrary, fit_mode_response
from .math import rot2
from .physics import MuJoCoAdapter, PhysicsState


@dataclass(frozen=True)
class SteadyCalibrationConfig:
    speeds_mps: tuple[float, ...] = (.06, .08, .10)
    yaws_rad: tuple[float, ...] = tuple(np.deg2rad(np.arange(0.0, 360.0, 45.0)).tolist())
    repeats: int = 2
    distance_m: float = .03
    max_ticks: int = 40
    warmup_ticks: int = 2
    min_steady_ticks: int = 5
    discard_ticks: int = 2
    pusher_radius: float = .018
    contact_clearance: float = .002
    tracking_gain: float = 8.0
    tracking_speed_limit: float = .06
    max_command_mps: float = .20
    engage_max_ticks: int = 4
    fixed_contact_tolerance_m: float = .001
    fixed_contact_point_tolerance_m: float = .002
    max_tilt_rad: float = np.deg2rad(5.0)
    corner_force_min_n: float = .05
    corner_normal_alignment: float = .70

    def __post_init__(self):
        if not self.speeds_mps or any(not np.isfinite(x) or x <= 0 or x > .30 for x in self.speeds_mps):
            raise ValueError("steady calibration speeds must lie in (0,.30]")
        if not self.yaws_rad or any(not np.isfinite(x) for x in self.yaws_rad):
            raise ValueError("steady calibration yaws must be finite and nonempty")
        if self.repeats < 1 or self.max_ticks < 1 or self.engage_max_ticks < 1 or self.warmup_ticks < 0 or self.min_steady_ticks < 1 or self.discard_ticks < 0:
            raise ValueError("invalid steady calibration counts")
        if min(self.distance_m, self.pusher_radius, self.contact_clearance, self.tracking_gain, self.tracking_speed_limit, self.max_command_mps, self.fixed_contact_tolerance_m, self.fixed_contact_point_tolerance_m, self.max_tilt_rad, self.corner_force_min_n) <= 0:
            raise ValueError("steady calibration scales must be positive")
        if not 0 < self.corner_normal_alignment <= 1:
            raise ValueError("corner normal alignment must be in (0,1]")


def engage_contact_command(state: PhysicsState, library: ModeLibrary, mode: int, speed: float, config: SteadyCalibrationConfig):
    """Move from the declared clearance point until contact is established.

    This command is used only before the strict calibration segment.  Its
    clearance/tracking terms are intentionally not used after the contact
    anchor has been latched.
    """

    mode = int(mode)
    rotation = rot2(float(state.object_q[2]))
    point = library.contact_points[mode]
    normal = library.normals[mode]
    tangent = library.tangents[mode]
    offset = float(library.contact_offset[mode])
    target = point + normal * offset
    local_pusher = rotation.T @ (state.pusher_position[:2] - state.object_q[:2])
    body_velocity = rotation.T @ state.object_velocity[:2]
    omega = float(state.object_angular_velocity[2])
    contact_velocity = body_velocity + omega * np.array([-target[1], target[0]])
    # During ENGAGE, correct only along the declared tangent.  The normal
    # component remains the active inward speed, so an outside clearance
    # target cannot cancel the approach before contact is made.
    tangent_error = float(tangent @ (target - local_pusher))
    tangent_speed = np.clip(
        float(tangent @ contact_velocity) + config.tracking_gain * tangent_error,
        -config.tracking_speed_limit,
        config.tracking_speed_limit,
    )
    command_body = tangent * tangent_speed - normal * float(speed)
    command_world = rotation @ command_body
    # Engagement is still checked by the caller; do not clip here and hide a
    # speed-contract violation in the calibration log.
    return command_world


def _fixed_contact_components(
    state: PhysicsState,
    anchor_body,
    normal_body,
    speed,
    tracking_gain=0.0,
    tangent_body=None,
    face_count=1,
):
    """Return the exact transport/drive decomposition for a fixed mode.

    ``anchor_body`` is the measured pusher-centre position relative to the
    object at the instant contact is latched.  It is never recomputed from a
    moving clearance target.  For one face, only the tangential component of
    the rigid-body anchor velocity is transported; the normal component is
    deliberately generated by the constant drive and the real unilateral
    contact constraint.  For a two-face corner, the full anchor velocity is
    transported because both face constraints must remain active.
    """

    anchor_body = np.asarray(anchor_body, dtype=np.float64)
    normal_body = np.asarray(normal_body, dtype=np.float64)
    if anchor_body.shape != (2,) or normal_body.shape != (2,):
        raise ValueError("fixed contact anchor and normal must have shape (2,)")
    if not np.isfinite(anchor_body).all() or not np.isfinite(normal_body).all():
        raise ValueError("fixed contact anchor and normal must be finite")
    normal_length = float(np.linalg.norm(normal_body))
    if not np.isclose(normal_length, 1.0, atol=1e-6, rtol=0):
        raise ValueError("fixed contact normal must be unit length")
    rotation = rot2(float(state.object_q[2]))
    body_velocity = rotation.T @ state.object_velocity[:2]
    omega = float(state.object_angular_velocity[2])
    actual_anchor_body = _body_xy(state, state.pusher_position[:2])
    anchor_error_body = anchor_body - actual_anchor_body
    tracking_correction_body = float(tracking_gain) * anchor_error_body
    contact_velocity_body = body_velocity + omega * np.array(
        [-anchor_body[1], anchor_body[0]], dtype=np.float64
    )
    if int(face_count) <= 1:
        if tangent_body is None:
            raise ValueError("single-face fixed contact requires a tangent")
        tangent_body = np.asarray(tangent_body, dtype=np.float64)
        tangent_length = float(np.linalg.norm(tangent_body))
        if not np.isclose(tangent_length, 1.0, atol=1e-6, rtol=0):
            raise ValueError("fixed contact tangent must be unit length")
        anchor_transport_body = tangent_body * float(tangent_body @ contact_velocity_body)
        tracking_correction_body = tangent_body * float(tangent_body @ tracking_correction_body)
        anchor_transport_body += tracking_correction_body
    else:
        anchor_transport_body = contact_velocity_body + tracking_correction_body
    push_direction_body = -normal_body
    drive_body = push_direction_body * float(speed)
    command_body = anchor_transport_body + drive_body
    return {
        "anchor_body": anchor_body.copy(),
        "normal_body": normal_body.copy(),
        "push_direction_body": push_direction_body,
        "contact_velocity_body": contact_velocity_body,
        "anchor_transport_body": anchor_transport_body,
        "tracking_correction_body": tracking_correction_body,
        "drive_body": drive_body,
        "command_body": command_body,
        "command_world": rotation @ command_body,
    }


def fixed_contact_command(
    state: PhysicsState,
    library: ModeLibrary,
    mode: int,
    speed: float,
    config: SteadyCalibrationConfig,
    anchor_body=None,
):
    """Command a strict fixed-contact moving mode.

    After ENGAGE, pass the latched ``anchor_body``.  The body-frame push
    direction is exactly ``-library.normals[mode]`` and the normal drive
    component has exactly the requested scalar speed.  The returned command
    is raw: it is not clipped, because clipping would violate the calibration
    contract and make a nominal speed look like a measured one.
    """

    mode = int(mode)
    if not 0 <= mode < library.count:
        raise ValueError("mode index out of range")
    if anchor_body is None:
        # This fallback is useful for callers that only need the nominal
        # command; the calibrator always supplies a measured latch.
        anchor_body = library.contact_points[mode] + library.normals[mode] * float(library.contact_offset[mode])
    return _fixed_contact_components(
        state,
        anchor_body,
        library.normals[mode],
        speed,
        tracking_gain=float(config.tracking_gain),
        tangent_body=library.tangents[mode],
        face_count=int(library.face_mask[mode].sum()),
    )["command_world"]


def _contact_valid(state, library, mode, config):
    contact = state.contact
    if not contact.active:
        return False
    expected = library.face_normals[mode][library.face_mask[mode]]
    if contact.pair_count < len(expected):
        return False
    rotation = rot2(float(state.object_q[2]))
    expected_world = np.c_[expected @ rotation.T, np.zeros(len(expected))]
    forces = np.linalg.norm(contact.pair_forces_world, axis=1)
    normals = contact.pair_normals_world
    used = set()
    for target in expected_world:
        scores = np.abs(normals @ target)
        for index in np.argsort(-scores):
            index = int(index)
            if index in used:
                continue
            if forces[index] >= config.corner_force_min_n and scores[index] >= config.corner_normal_alignment:
                used.add(index)
                break
        else:
            return False
    return True


def _body_xy(state, world_xy):
    """Transform a world XY point into the current object frame."""

    return rot2(-float(state.object_q[2])) @ (
        np.asarray(world_xy, dtype=np.float64).reshape(2) - state.object_q[:2]
    )


def _normal_alignment(state, library, mode):
    """Return the worst measured face-normal line alignment in body coordinates."""

    if not state.contact.active or state.contact.pair_count < 1:
        return 0.0
    expected = library.face_normals[mode][library.face_mask[mode]]
    actual = state.contact.pair_normals_world[:, :2]
    rotation = rot2(float(state.object_q[2]))
    actual_body = actual @ rotation
    scores = np.abs(actual_body @ expected.T)
    return float(np.min(np.max(scores, axis=0))) if len(scores) else 0.0


def _fixed_contact_measurement(state, anchor_body, contact_anchor_body):
    """Measure the two fixed-point residuals and actual relative velocity."""

    actual_anchor_body = _body_xy(state, state.pusher_position[:2])
    anchor_error_body = actual_anchor_body - anchor_body
    if state.contact.active:
        actual_contact_body = _body_xy(state, state.contact.point_world[:2])
        contact_error_body = actual_contact_body - contact_anchor_body
    else:
        actual_contact_body = np.zeros(2, dtype=np.float64)
        contact_error_body = np.full(2, np.inf, dtype=np.float64)
    rotation = rot2(float(state.object_q[2]))
    body_velocity = rotation.T @ state.object_velocity[:2]
    actual_pusher_velocity_body = rotation.T @ state.pusher_velocity[:2]
    contact_velocity_body = body_velocity + float(state.object_angular_velocity[2]) * np.array(
        [-anchor_body[1], anchor_body[0]], dtype=np.float64
    )
    relative_velocity_body = actual_pusher_velocity_body - contact_velocity_body
    return {
        "actual_anchor_body": actual_anchor_body,
        "anchor_error_body": anchor_error_body,
        "actual_contact_body": actual_contact_body,
        "contact_error_body": contact_error_body,
        "actual_pusher_velocity_body": actual_pusher_velocity_body,
        "relative_velocity_body": relative_velocity_body,
    }


def _trend(values, dt):
    values = np.asarray(values, dtype=np.float64)
    if len(values) < 2:
        return ([0.0] * values.shape[1] if values.ndim == 2 else 0.0), 0.0
    time = np.arange(len(values), dtype=np.float64) * float(dt)
    slopes = []
    for column in range(values.shape[1] if values.ndim == 2 else 1):
        y = values[:, column] if values.ndim == 2 else values
        slopes.append(float(np.polyfit(time, y, 1)[0]))
    return slopes if values.ndim == 2 else slopes[0], float(np.sqrt(np.mean(np.square(values - np.mean(values, axis=0)))))


class SteadyModeCalibrator:
    """Calibrate all fixed modes from distance-based steady trajectories."""

    def __init__(self, adapter: MuJoCoAdapter, config: SteadyCalibrationConfig | None = None):
        self.adapter = adapter
        self.config = config or SteadyCalibrationConfig()

    def _run(self, library, mode, yaw, speed, repeat):
        point = library.contact_points[mode]
        normal = library.normals[mode]
        center = point + normal * library.contact_offset[mode]
        pusher = rot2(float(yaw)) @ center
        state = self.adapter.reset((0., 0., float(yaw)), pusher)
        engage_rows = []
        anchor_body = None
        contact_anchor_body = None
        for engage_tick in range(self.config.engage_max_ticks):
            commands = []
            contact_established = False
            engage_saturated = False
            for _ in range(self.adapter.substeps):
                command = engage_contact_command(state, library, mode, speed, self.config)
                if not np.isfinite(command).all() or np.any(np.abs(command) > self.config.max_command_mps + 1e-12):
                    engage_saturated = True
                    break
                commands.append(command.copy())
                self.adapter.step_physics(command)
                state = self.adapter.observe()
                if _contact_valid(state, library, mode, self.config):
                    contact_established = True
                    break
            engage_rows.append({
                "tick": engage_tick,
                "physics_steps": len(commands),
                "command_world_xy_mps": np.mean(commands, axis=0).tolist() if commands else [0., 0.],
                "contact_active": bool(state.contact.active),
                "contact_pairs": int(state.contact.pair_count),
                "contact_force_norm_n": float(state.contact.force_norm),
                "contact_valid": bool(contact_established),
                "command_saturated": engage_saturated,
            })
            if contact_established:
                # The actual contact state, not the pre-contact clearance
                # target, is the immutable body-frame anchor for this run.
                anchor_body = _body_xy(state, state.pusher_position[:2])
                contact_anchor_body = _body_xy(state, state.contact.point_world[:2])
                break
        if anchor_body is None:
            return {
                "mode": mode, "yaw_rad": yaw, "speed_mps": speed, "repeat": repeat,
                "valid": False, "reached_distance": False, "rows": [], "steady_rows": [],
                "engage_rows": engage_rows, "usable_anchor": False,
                "reason": "contact_not_established_before_latch",
            }
        run_start_q = state.object_q.copy()
        rows = []
        violation_reason = None
        commanded_drive_displacement_body = np.zeros(2, dtype=np.float64)
        for tick in range(self.config.max_ticks):
            tick_valid = True
            tick_reason = None
            commands = []
            max_anchor_error = 0.0
            max_contact_error = 0.0
            min_alignment = 1.0
            last_parts = None
            physics_steps = 0
            for _ in range(self.adapter.substeps):
                parts = _fixed_contact_components(
                    state,
                    anchor_body,
                    normal,
                    speed,
                    tracking_gain=float(self.config.tracking_gain),
                    tangent_body=library.tangents[mode],
                    face_count=int(library.face_mask[mode].sum()),
                )
                last_parts = parts
                command = parts["command_world"]
                correction_saturated = bool(
                    np.linalg.norm(parts["tracking_correction_body"]) > self.config.tracking_speed_limit + 1e-12
                )
                command_saturated = bool(
                    not np.isfinite(command).all()
                    or np.any(np.abs(command) > self.config.max_command_mps + 1e-12)
                )
                if correction_saturated or command_saturated:
                    tick_valid = False
                    tick_reason = "anchor_tracking_saturated" if correction_saturated else "command_saturated"
                    break
                commands.append(command.copy())
                commanded_drive_displacement_body += parts["drive_body"] * float(self.adapter.physics_dt)
                self.adapter.step_physics(command)
                state = self.adapter.observe()
                physics_steps += 1
                measurement = _fixed_contact_measurement(state, anchor_body, contact_anchor_body)
                anchor_error = float(np.linalg.norm(measurement["anchor_error_body"]))
                contact_error = float(np.linalg.norm(measurement["contact_error_body"]))
                max_anchor_error = max(max_anchor_error, anchor_error)
                max_contact_error = max(max_contact_error, contact_error)
                alignment = _normal_alignment(state, library, mode)
                min_alignment = min(min_alignment, alignment)
                substep_valid = bool(
                    _contact_valid(state, library, mode, self.config)
                    and anchor_error <= self.config.fixed_contact_tolerance_m
                    and contact_error <= self.config.fixed_contact_point_tolerance_m
                    and abs(state.roll) <= self.config.max_tilt_rad
                    and abs(state.pitch) <= self.config.max_tilt_rad
                )
                if not substep_valid:
                    tick_valid = False
                    if not _contact_valid(state, library, mode, self.config):
                        tick_reason = "contact_or_normal_invalid"
                    elif anchor_error > self.config.fixed_contact_tolerance_m:
                        tick_reason = "fixed_pusher_anchor_drift"
                    elif contact_error > self.config.fixed_contact_point_tolerance_m:
                        tick_reason = "fixed_object_contact_point_drift"
                    else:
                        tick_reason = "tilt_limit"
                    break
            if last_parts is None:
                last_parts = _fixed_contact_components(
                    state,
                    anchor_body,
                    normal,
                    speed,
                    tracking_gain=float(self.config.tracking_gain),
                    tangent_body=library.tangents[mode],
                    face_count=int(library.face_mask[mode].sum()),
                )
            measurement = _fixed_contact_measurement(state, anchor_body, contact_anchor_body)
            body_velocity = rot2(-float(state.object_q[2])) @ state.object_velocity[:2]
            distance = float(np.linalg.norm(state.object_q[:2] - run_start_q[:2]))
            if tick_reason is not None and violation_reason is None:
                violation_reason = tick_reason
            rows.append({
                "tick": tick,
                "yaw_rad": float(yaw),
                "speed_mps": float(speed),
                "repeat": int(repeat),
                "object_q": state.object_q.copy().tolist(),
                "velocity_world_xy_mps": state.object_velocity[:2].copy().tolist(),
                "velocity_body_xy_mps": body_velocity.tolist(),
                "omega_radps": float(state.object_angular_velocity[2]),
                "physics_steps": physics_steps,
                "command_world_xy_mps": np.mean(commands, axis=0).tolist() if commands else last_parts["command_world"].tolist(),
                "command_body_xy_mps": last_parts["command_body"].copy().tolist(),
                "contact_transport_body_xy_mps": last_parts["contact_velocity_body"].copy().tolist(),
                "transport_command_body_xy_mps": last_parts["anchor_transport_body"].copy().tolist(),
                "tracking_correction_body_xy_mps": last_parts["tracking_correction_body"].copy().tolist(),
                "drive_command_body_xy_mps": last_parts["drive_body"].copy().tolist(),
                "push_direction_body": last_parts["push_direction_body"].copy().tolist(),
                "drive_speed_mps": float(speed),
                "commanded_ball_drive_displacement_body_m": commanded_drive_displacement_body.tolist(),
                "actual_pusher_velocity_body_xy_mps": measurement["actual_pusher_velocity_body"].tolist(),
                "relative_contact_velocity_body_xy_mps": measurement["relative_velocity_body"].tolist(),
                "fixed_anchor_body": anchor_body.copy().tolist(),
                "actual_anchor_body": measurement["actual_anchor_body"].tolist(),
                "fixed_anchor_error_body_m": measurement["anchor_error_body"].tolist(),
                "fixed_anchor_error_norm_m": max_anchor_error,
                "fixed_contact_point_body": contact_anchor_body.copy().tolist(),
                "actual_contact_point_body": measurement["actual_contact_body"].tolist(),
                "fixed_contact_point_error_body_m": measurement["contact_error_body"].tolist(),
                "fixed_contact_point_error_norm_m": max_contact_error,
                "normal_alignment": min_alignment,
                "contact_active": bool(state.contact.active),
                "contact_pairs": int(state.contact.pair_count),
                "contact_force_norm_n": float(state.contact.force_norm),
                "roll_rad": float(state.roll),
                "pitch_rad": float(state.pitch),
                "valid": bool(tick_valid),
                "reason": tick_reason,
                "distance_from_start_m": distance,
            })
            if not np.isfinite(state.object_q).all():
                violation_reason = "nonfinite_state"
                break
            minimum_run_ticks = self.config.warmup_ticks + self.config.discard_ticks + self.config.min_steady_ticks
            if not tick_valid:
                break
            if distance >= self.config.distance_m and tick + 1 >= minimum_run_ticks:
                break
        valid_indices = [index for index, row in enumerate(rows) if row["valid"]]
        steady_indices = [
            index for index in valid_indices
            if index >= self.config.warmup_ticks + self.config.discard_ticks
        ]
        steady = [rows[index] for index in steady_indices]
        reached = bool(rows and rows[-1].get("distance_from_start_m", 0.0) >= self.config.distance_m)
        strict_rows_ok = bool(rows and all(row.get("valid", False) for row in rows))
        if len(steady) < self.config.min_steady_ticks or not reached or not strict_rows_ok:
            reason = violation_reason
            if reason is None:
                reason = "distance_not_reached" if not reached else (
                    "insufficient_steady_contact" if len(steady) < self.config.min_steady_ticks
                    else "strict_fixed_contact_violation"
                )
            return {"mode": mode, "yaw_rad": yaw, "speed_mps": speed, "repeat": repeat,
                    "valid": False, "reached_distance": reached, "rows": rows, "steady_rows": steady,
                    "engage_rows": engage_rows, "usable_anchor": True,
                    "anchor_body": anchor_body.tolist(), "contact_anchor_body": contact_anchor_body.tolist(),
                    "max_distance_m": max((row.get("distance_from_start_m", 0.0) for row in rows), default=0.0),
                    "reason": reason}
        return {"mode": mode, "yaw_rad": yaw, "speed_mps": speed, "repeat": repeat,
                "valid": True, "reached_distance": True, "rows": rows, "steady_rows": steady,
                "engage_rows": engage_rows, "usable_anchor": True,
                "anchor_body": anchor_body.tolist(), "contact_anchor_body": contact_anchor_body.tolist(),
                "max_distance_m": max((row["distance_from_start_m"] for row in rows), default=0.0),
                "distance_m": rows[-1]["distance_from_start_m"]}

    def calibrate(self, library: ModeLibrary, output=None):
        result = library.copy()
        all_modes = []
        for mode in range(result.count):
            runs = []
            for yaw in self.config.yaws_rad:
                for speed in self.config.speeds_mps:
                    for repeat in range(self.config.repeats):
                        try:
                            runs.append(self._run(result, mode, yaw, speed, repeat))
                        except (FloatingPointError, RuntimeError, ValueError) as exc:
                            runs.append({"mode": mode, "yaw_rad": yaw, "speed_mps": speed, "repeat": repeat,
                                         "valid": False, "rows": [], "steady_rows": [], "reason": type(exc).__name__})
            usable = [run for run in runs if run.get("valid") and run.get("reached_distance")]
            body_means = []
            inputs = []
            steady_rows = [row for run in usable for row in run["steady_rows"]]
            for run in usable:
                body = np.asarray([row["velocity_body_xy_mps"] + [row["omega_radps"]] for row in run["steady_rows"]], dtype=np.float64)
                body_means.append(body.mean(axis=0))
                inputs.append(run["speed_mps"])
            if body_means:
                response, fit_error = fit_mode_response(np.asarray(body_means), np.asarray(inputs))
            else:
                response, fit_error = np.zeros(3), np.inf
            result.c[:, mode] = response
            result.fit_error[mode] = fit_error
            result.u_min[mode] = min((run["speed_mps"] for run in usable), default=0.0)
            result.u_max[mode] = max((run["speed_mps"] for run in usable), default=max(self.config.speeds_mps))
            result.hold_rate[mode] = float(len(usable) / max(len(runs), 1))
            result.valid[mode] = bool(
                len(usable) >= 2
                and result.hold_rate[mode] >= .5
                and fit_error <= .20
                and np.linalg.norm(response) > 1e-10
            )
            world = np.asarray([row["velocity_world_xy_mps"] for row in steady_rows], dtype=np.float64).reshape(-1, 2)
            body = np.asarray([row["velocity_body_xy_mps"] for row in steady_rows], dtype=np.float64).reshape(-1, 2)
            omega = np.asarray([row["omega_radps"] for row in steady_rows], dtype=np.float64)
            world_trend, world_spread = _trend(world, self.adapter.control_dt)
            body_trend, body_spread = _trend(body, self.adapter.control_dt)
            omega_trend, omega_spread = _trend(omega, self.adapter.control_dt)
            speed_summaries = {}
            for speed in self.config.speeds_mps:
                speed_rows = [
                    row for run in usable if np.isclose(run["speed_mps"], speed, atol=1e-12, rtol=0)
                    for row in run["steady_rows"]
                ]
                speed_world = np.asarray([row["velocity_world_xy_mps"] for row in speed_rows], dtype=np.float64).reshape(-1, 2)
                speed_body = np.asarray([row["velocity_body_xy_mps"] for row in speed_rows], dtype=np.float64).reshape(-1, 2)
                speed_omega = np.asarray([row["omega_radps"] for row in speed_rows], dtype=np.float64)
                speed_world_trend, _ = _trend(speed_world, self.adapter.control_dt)
                speed_body_trend, _ = _trend(speed_body, self.adapter.control_dt)
                speed_omega_trend, _ = _trend(speed_omega, self.adapter.control_dt)
                speed_summaries[str(float(speed))] = {
                    "steady_tick_count": int(len(speed_rows)),
                    "world_velocity_mean_mps": speed_world.mean(axis=0).tolist() if len(speed_world) else [0., 0.],
                    "world_velocity_std_mps": speed_world.std(axis=0).tolist() if len(speed_world) else [0., 0.],
                    "body_velocity_mean_mps": speed_body.mean(axis=0).tolist() if len(speed_body) else [0., 0.],
                    "body_velocity_std_mps": speed_body.std(axis=0).tolist() if len(speed_body) else [0., 0.],
                    "omega_mean_radps": float(speed_omega.mean()) if len(speed_omega) else 0.,
                    "omega_std_radps": float(speed_omega.std()) if len(speed_omega) else 0.,
                    "world_velocity_trend_mps2": speed_world_trend,
                    "body_velocity_trend_mps2": speed_body_trend,
                    "omega_trend_radps2": float(speed_omega_trend),
                }
            all_modes.append({
                "mode": mode,
                "mode_type": str(result.mode_type[mode]),
                "runs": runs,
                "usable_runs": len(usable),
                "steady_tick_count": len(steady_rows),
                "max_distance_m": float(max((row.get("distance_from_start_m", 0.0) for run in runs for row in run.get("rows", [])), default=0.0)),
                "response_c_i": response.tolist(),
                "fit_error": float(fit_error),
                "hold_rate": float(result.hold_rate[mode]),
                "valid": bool(result.valid[mode]),
                "steady_velocity_world_mean_mps": world.mean(axis=0).tolist() if len(world) else [0., 0.],
                "steady_velocity_world_std_mps": world.std(axis=0).tolist() if len(world) else [0., 0.],
                "steady_velocity_body_mean_mps": body.mean(axis=0).tolist() if len(body) else [0., 0.],
                "steady_velocity_body_std_mps": body.std(axis=0).tolist() if len(body) else [0., 0.],
                "steady_omega_mean_radps": float(omega.mean()) if len(omega) else 0.,
                "steady_omega_std_radps": float(omega.std()) if len(omega) else 0.,
                "velocity_world_trend_mps2": world_trend,
                "velocity_body_trend_mps2": body_trend,
                "omega_trend_radps2": float(omega_trend),
                "world_spread": world_spread,
                "body_spread": body_spread,
                "omega_spread": omega_spread,
                "speed_summaries": speed_summaries,
            })
        result.metadata.update({
            "calibration": "strict fixed-contact-point distance run",
            "contact_constraint": "latched pusher centre and measured object contact point remain fixed in the object frame",
            "push_direction_constraint": "drive component is -u times the declared body-frame outward normal",
            "drive_speed_definition": "u is the actively generated normal drive speed; transport and measured object velocity are separate channels",
            "low_level_command_update": "recomputed every physics step while report rows remain one control_dt",
            "steady_calibration_config": json_safe(self.config.__dict__),
            "steady_mode_results": json_safe(all_modes),
        })
        if output is not None:
            output = __import__("pathlib").Path(output)
            output.mkdir(parents=True, exist_ok=True)
            (output / "steady_calibration.json").write_text(json.dumps(json_safe(all_modes), indent=2, ensure_ascii=False) + "\n")
            rows = []
            for mode_result in all_modes:
                for run in mode_result["runs"]:
                    for row in run.get("rows", []):
                        world_velocity = row.get("velocity_world_xy_mps", [np.nan, np.nan])
                        body_velocity = row.get("velocity_body_xy_mps", [np.nan, np.nan])
                        rows.append([
                            mode_result["mode"], row["yaw_rad"], row["speed_mps"], row["repeat"], row["tick"],
                            int(row["valid"]), *world_velocity, *body_velocity,
                            row.get("omega_radps", np.nan), row.get("contact_pairs", -1), row.get("contact_force_norm_n", np.nan),
                            row.get("roll_rad", np.nan), row.get("pitch_rad", np.nan), row.get("distance_from_start_m", np.nan),
                        ])
            columns = np.asarray([
                "mode", "yaw_rad", "speed_mps", "repeat", "tick", "valid",
                "world_vx_mps", "world_vy_mps", "body_vx_mps", "body_vy_mps",
                "omega_radps", "contact_pairs", "contact_force_norm_n",
                "roll_rad", "pitch_rad", "distance_from_start_m",
            ], dtype="U32")
            np.savez_compressed(
                output / "steady_velocity_samples.npz",
                values=np.asarray(rows, dtype=np.float64),
                columns=columns,
            )
        return result, all_modes
